@if(session('success') || session('error'))<div x-data="{show:true}" x-show="show" x-init="setTimeout(()=>show=false,4500)" class="mb-6 flex items-center justify-between rounded-xl border px-4 py-3 {{ session('success') ? 'border-primary/20 bg-secondary/40 text-primary' : 'border-red-200 bg-red-50 text-red-700' }}"><span>{{ session('success') ?? session('error') }}</span><button @click="show=false" aria-label="Dismiss">×</button></div>@endif
